m['answer']??''));$guidance=trim((string)($item['marking_guidance']??''));$objectives=trim((string)($item['learning_objectives']??''));$difficulty=(string)($item['difficulty']??'');if($prompt===''||mb_strlen($prompt)>30000||$answer===''||mb_strlen($answer)>30000||mb_strlen($guidance)>12000||mb_strlen($objectives)>6000||!in_array($difficulty,['easy','moderate','challenging'],true))throw new DomainException('A generated question is missing valid prompt, answer, objective, guidance or difficulty.');$options=$item['options']??[];if($style==='multiple_choice'){$options=array_values(array_filter(array_map(static fn($v)=>is_string($v)?trim($v):'',is_array($options)?$options:[]),static fn($v)=>$v!==''));if(count($options)!==4||count(array_unique($options))!==4||!in_array($answer,$options,true))throw new DomainException('Generated multiple-choice questions need four distinct options and a model answer matching one option.');foreach($options as $option)if(mb_strlen($option)>1000)throw new DomainException('A generated multiple-choice option is too long.');}else{$options=[];}$clean[]=['type'=>$styles[$style],'prompt'=>$prompt,'options'=>$options,'answer'=>$answer,'guidance'=>$guidance,'objectives'=>$objectives,'difficulty'=>$difficulty];}$db->beginTransaction();try{$q=$db->prepare("INSERT INTO ai_question_import_batches(school_id,created_by,import_key,question_ids) VALUES(?,?,?,'[]')");$q->execute([$schoolId,$uid,$importKey]);$batchId=(int)$db->lastInsertId();}catch(PDOException $e){if($db->inTransaction())$db->rollBack();if($e->getCode()==='23000'){$q=$db->prepare('SELECT question_ids FROM ai_question_import_batches WHERE school_id=? AND created_by=? AND import_key=?');$q->execute([$schoolId,$uid,$importKey]);$existing=$q->fetchColumn();if($existing!==false){$ids=json_decode((string)$existing,true)?:[];qb_ok('This generated set was already imported.',['question_ids'=>$ids,'count'=>count($ids),'reused'=>true]);}}throw $e;}$insert=$db->prepare("INSERT INTO question_bank(school_i